package com.tracker.entity;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="verification_history") @Getter @Setter @NoArgsConstructor
public class VerificationHistory { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="certification_id") @JsonIgnore private Certification certification; @ManyToOne(optional=false) @JoinColumn(name="admin_id") @JsonIgnore private User admin; @Enumerated(EnumType.STRING) private CertStatus previousStatus; @Enumerated(EnumType.STRING) private CertStatus newStatus; private String remarks; private LocalDateTime verifiedAt; @PrePersist void created(){verifiedAt=LocalDateTime.now();} public Long getCertificationId(){return certification.getId();} public String getCertificationName(){return certification.getCertificationName();} public String getStudentName(){return certification.getUser().getName();} public String getAdminName(){return admin.getName();} }
